	,applyScore: function(score,daRating,healthChange,isComboBreak) {
		switch(daRating) {
		case "bad":
			funkin_Highscore.tallies.bad += 1;
			break;
		case "good":
			funkin_Highscore.tallies.good += 1;
			break;
		case "miss":
			funkin_Highscore.tallies.missed += 1;
			break;
		case "shit":
			funkin_Highscore.tallies.shit += 1;
			break;
		case "sick":
			funkin_Highscore.tallies.sick += 1;
			break;
		}
		this.health += healthChange;
		if(isComboBreak) {
			if(funkin_Highscore.tallies.combo >= 10) {
				this.comboPopUps.displayCombo(0);
			}
			funkin_Highscore.tallies.combo = 0;
		} else {
			funkin_Highscore.tallies.combo++;
			if(funkin_Highscore.tallies.combo > funkin_Highscore.tallies.maxCombo) {
				funkin_Highscore.tallies.maxCombo = funkin_Highscore.tallies.combo;
			}
		}
		this.songScore += score;
	}
