	,handleCutsceneKeys: function(elapsed) {
		if(this.get_isGamePaused()) {
			return;
		}
		if(this.currentConversation != null) {
			if(funkin_PlayerSettings.player1.controls._cutscene_advance.check() && !this.justUnpaused) {
				this.currentConversation.advanceConversation();
			} else if(funkin_PlayerSettings.player1.controls._pause.check() && !this.justUnpaused) {
				this.currentConversation.pauseMusic();
				var pauseSubState = new funkin_play_PauseSubState({ mode : funkin_play_PauseMode.Conversation});
				this.persistentUpdate = false;
				flixel_addons_transition_FlxTransitionableState.skipNextTransIn = true;
				flixel_addons_transition_FlxTransitionableState.skipNextTransOut = true;
				pauseSubState.set_camera(this.camCutscene);
				this.openSubState(pauseSubState);
			}
		} else if(funkin_play_cutscene_VideoCutscene.isPlaying()) {
			if(funkin_PlayerSettings.player1.controls._pause.check() && !this.justUnpaused) {
				funkin_play_cutscene_VideoCutscene.pauseVideo();
				var pauseSubState = new funkin_play_PauseSubState({ mode : funkin_play_PauseMode.Cutscene});
				this.persistentUpdate = false;
				flixel_addons_transition_FlxTransitionableState.skipNextTransIn = true;
				flixel_addons_transition_FlxTransitionableState.skipNextTransOut = true;
				pauseSubState.set_camera(this.camCutscene);
				this.openSubState(pauseSubState);
			}
		}
	}
