	,sortSongs: function(songsToFilter,songFilter) {
		var filterAlphabetically = function(a,b) {
			if((a != null ? a.songName.toLowerCase() : null) < (b != null ? b.songName.toLowerCase() : null)) {
				return -1;
			} else if((a != null ? a.songName.toLowerCase() : null) > (b != null ? b.songName.toLowerCase() : null)) {
				return 1;
			} else {
				return 0;
			}
		};
		switch(songFilter.filterType) {
		case "ALL":
			break;
		case "FAVORITE":
			var _g = [];
			var _g1 = 0;
			var _g2 = songsToFilter;
			while(_g1 < _g2.length) {
				var v = _g2[_g1];
				++_g1;
				if(v == null ? true : v.isFav) {
					_g.push(v);
				}
			}
			songsToFilter = _g;
			songsToFilter.sort(filterAlphabetically);
			break;
		case "REGEXP":
			var filterRegexp = new EReg("^[" + Std.string(songFilter.filterData) + "].*","i");
			var _g = [];
			var _g1 = 0;
			var _g2 = songsToFilter;
			while(_g1 < _g2.length) {
				var v = _g2[_g1];
				++_g1;
				if(v == null ? true : filterRegexp.match(v.songName)) {
					_g.push(v);
				}
			}
			songsToFilter = _g;
			songsToFilter.sort(filterAlphabetically);
			break;
		case "STARTSWITH":
			var _g = [];
			var _g1 = 0;
			var _g2 = songsToFilter;
			while(_g1 < _g2.length) {
				var v = _g2[_g1];
				++_g1;
				if(v == null ? true : StringTools.startsWith(v.songName.toLowerCase(),songFilter.filterData)) {
					_g.push(v);
				}
			}
			songsToFilter = _g;
			break;
		default:
		}
		return songsToFilter;
	}
