	,loadPreferences: function() {
		var save = funkin_save_Save.get_instance();
		if(this.previousWorkingFilePaths[0] == null) {
			this.set_previousWorkingFilePaths([null].concat(save.get_chartEditorPreviousFiles()));
		} else {
			this.set_previousWorkingFilePaths([this.get_currentWorkingFilePath()].concat(save.get_chartEditorPreviousFiles()));
		}
		this.noteSnapQuantIndex = save.get_chartEditorNoteQuant();
		this.currentLiveInputStyle = save.get_chartEditorLiveInputStyle();
		this.set_isViewDownscroll(save.get_chartEditorDownscroll());
		this.playtestStartTime = save.get_chartEditorPlaytestStartTime();
		this.set_currentTheme(save.get_chartEditorTheme());
		this.metronomeVolume = save.get_chartEditorMetronomeVolume();
		this.hitsoundVolumePlayer = save.get_chartEditorHitsoundVolumePlayer();
		this.hitsoundVolumePlayer = save.get_chartEditorHitsoundVolumeOpponent();
		this.welcomeMusic.set_active(save.get_chartEditorThemeMusic());
	}
	,writePreferences: function(hasBackup) {
		var save = funkin_save_Save.get_instance();
		var filteredWorkingFilePaths = [];
		var _g = 0;
		var _g1 = this.previousWorkingFilePaths;
		while(_g < _g1.length) {
			var chartPath = _g1[_g];
			++_g;
			if(chartPath != null) {
				filteredWorkingFilePaths.push(chartPath);
			}
		}
		save.set_chartEditorPreviousFiles(filteredWorkingFilePaths);
		if(hasBackup) {
			haxe_Log.trace("Queuing backup prompt for next time!",{ fileName : "source/funkin/ui/debug/charting/ChartEditorState.hx", lineNumber : 2300, className : "funkin.ui.debug.charting.ChartEditorState", methodName : "writePreferences"});
		}
		save.set_chartEditorHasBackup(hasBackup);
		save.set_chartEditorNoteQuant(this.noteSnapQuantIndex);
		save.set_chartEditorLiveInputStyle(this.currentLiveInputStyle);
		save.set_chartEditorDownscroll(this.isViewDownscroll);
		save.set_chartEditorPlaytestStartTime(this.playtestStartTime);
		save.set_chartEditorTheme(this.currentTheme);
		save.set_chartEditorMetronomeVolume(this.metronomeVolume);
		save.set_chartEditorHitsoundVolumePlayer(this.hitsoundVolumePlayer);
		save.set_chartEditorHitsoundVolumeOpponent(this.hitsoundVolumeOpponent);
		save.set_chartEditorThemeMusic(this.welcomeMusic.active);
	}
