	,calculateNotePreviewViewportBounds: function() {
		var bounds = new flixel_math_FlxRect();
		if(this.notePreview == null) {
			return bounds;
		}
		bounds.x = this.notePreview.x;
		bounds.width = this.notePreview.get_width();
		bounds.y = this.notePreview.y + this.notePreview.get_height() * (this.scrollPositionInPixels / this.get_songLengthInPixels());
		bounds.height = this.notePreview.get_height() * (flixel_FlxG.height / this.get_songLengthInPixels());
		if(bounds.y < this.notePreview.y) {
			bounds.height -= this.notePreview.y - bounds.y;
			bounds.y = this.notePreview.y;
		} else if(bounds.y + bounds.height > this.notePreview.y + this.notePreview.get_height()) {
			bounds.height -= bounds.y + bounds.height - (this.notePreview.y + this.notePreview.get_height());
		}
		var MIN_HEIGHT = 8;
		if(bounds.height < MIN_HEIGHT) {
			bounds.y -= MIN_HEIGHT - bounds.height;
			bounds.height = MIN_HEIGHT;
		}
		return bounds;
	}
