	,handlePlaybar: function() {
		if(this.playbarHeadLayout == null) {
			throw haxe_Exception.thrown("ERROR: Tried to handle playbar, but playbarHeadLayout is null!");
		}
		this.playbarHeadLayout.set_x(4);
		this.playbarHeadLayout.set_y(flixel_FlxG.height - 48 - 8);
		if(!this.playbarHeadDragging) {
			var songPosPercent = this.scrollPositionInPixels / this.get_songLengthInPixels() * 100;
			if(this.playbarHeadLayout.playbarHead.get_value() != songPosPercent) {
				this.playbarHeadLayout.playbarHead.set_value(songPosPercent);
			}
		}
		var songPos = funkin_Conductor.get_instance().songPosition + funkin_Conductor.get_instance().instrumentalOffset;
		var songPosSeconds = StringTools.lpad(Std.string(Math.floor(Math.abs(songPos) / 1000 % 60)),"0",2);
		var songPosMinutes = StringTools.lpad(Std.string(Math.floor(Math.abs(songPos) / 1000 / 60)),"0",2);
		if(songPos < 0) {
			songPosMinutes = "-" + songPosMinutes;
		}
		var songPosString = "" + songPosMinutes + ":" + songPosSeconds;
		if(this.playbarSongPos.get_value() != songPosString) {
			this.playbarSongPos.set_value(songPosString);
		}
		var songRemaining = Math.max(this.get_songLengthInMs() - songPos,0.0);
		var songRemainingSeconds = StringTools.lpad(Std.string(Math.floor(songRemaining / 1000 % 60)),"0",2);
		var songRemainingMinutes = StringTools.lpad(Std.string(Math.floor(songRemaining / 1000 / 60)),"0",2);
		var songRemainingString = "-" + songRemainingMinutes + ":" + songRemainingSeconds;
		if(this.playbarSongRemaining.get_value() != songRemainingString) {
			this.playbarSongRemaining.set_value(songRemainingString);
		}
		this.playbarNoteSnap.set_text("1/" + this.get_noteSnapQuant());
		this.playbarDifficulty.set_text("" + funkin_util_tools_StringTools.toTitleCase(this.selectedDifficulty));
		var tmp = this.playbarBPM;
		var tmp1 = funkin_Conductor.get_instance().get_bpm();
		tmp.set_text("BPM: " + (tmp1 != null ? tmp1 : 0.0));
	}
