	,testSongInPlayState: function(minimal) {
		if(minimal == null) {
			minimal = false;
		}
		var _gthis = this;
		this.autoSave(true);
		this.stopWelcomeMusic();
		this.stopAudioPlayback();
		var startTimestamp = 0;
		if(this.playtestStartTime) {
			startTimestamp = this.get_scrollPositionInMs() + this.get_playheadPositionInMs();
		}
		var tmp = this.menubarItemPlaybackSpeed.get_value();
		var playbackRate = (tmp != null ? tmp : 1.0) * 2.0 / 100.0;
		playbackRate = Math.floor(playbackRate / 0.05) * 0.05;
		playbackRate = Math.max(0.05,Math.min(2.0,playbackRate));
		var targetSong;
		try {
			targetSong = funkin_play_song_Song.buildRaw(this.get_currentSongId(),funkin_util_tools_MapTools.values(this.songMetadata),this.get_availableVariations(),this.songChartData,this.playtestSongScripts,false);
		} catch( _g ) {
			var e = haxe_Exception.caught(_g);
			funkin_ui_debug_charting_handlers_ChartEditorNotificationHandler.error(this,"Could Not Playtest","Got an error trying to playtest the song.\n" + Std.string(e));
			return;
		}
		switch(this.get_currentSongStage()) {
		case "limoRide":
			funkin_play_PlayStatePlaylist.campaignId = "week4";
			break;
		case "mainStage":
			funkin_play_PlayStatePlaylist.campaignId = "week1";
			break;
		case "mallEvil":case "mallXmas":
			funkin_play_PlayStatePlaylist.campaignId = "week5";
			break;
		case "phillyBlazin":case "phillyBlazin2":case "phillyStreets":
			funkin_play_PlayStatePlaylist.campaignId = "weekend1";
			break;
		case "phillyTrain":
			funkin_play_PlayStatePlaylist.campaignId = "week3";
			break;
		case "school":case "schoolEvil":
			funkin_play_PlayStatePlaylist.campaignId = "week6";
			break;
		case "spookyMansion":
			funkin_play_PlayStatePlaylist.campaignId = "week2";
			break;
		case "tankmanBattlefield":
			funkin_play_PlayStatePlaylist.campaignId = "week7";
			break;
		}
		funkin_Paths.setCurrentLevel(funkin_play_PlayStatePlaylist.campaignId);
		this.get_subStateClosed().add($bind(this,this.reviveUICamera));
		this.get_subStateClosed().add($bind(this,this.resetConductorAfterTest));
		flixel_addons_transition_FlxTransitionableState.skipNextTransIn = false;
		flixel_addons_transition_FlxTransitionableState.skipNextTransOut = false;
		var targetStateParams = { targetSong : targetSong, targetDifficulty : this.selectedDifficulty, targetVariation : this.selectedVariation, practiceMode : this.playtestPracticeMode, botPlayMode : this.playtestBotPlayMode, minimalMode : minimal, startTimestamp : startTimestamp, playbackRate : playbackRate, overrideMusic : true};
		if(this.audioInstTrack != null) {
			flixel_FlxG.sound.music = this.audioInstTrack;
		}
		this.uiCamera.kill();
		flixel_FlxG.cameras.remove(this.uiCamera,false);
		flixel_FlxG.cameras.reset(new funkin_graphics_FunkinCamera("chartEditorUI2"));
		this.persistentUpdate = false;
		this.persistentDraw = false;
		this.stopWelcomeMusic();
		funkin_ui_transition_LoadingState.loadPlayState(targetStateParams,false,true,function(targetState) {
			targetState.vocals = _gthis.audioVocalTrackGroup;
		});
	}
	,performCommand: function(command,purgeRedoStack) {
		if(purgeRedoStack == null) {
			purgeRedoStack = true;
		}
		command.execute(this);
		if(command.shouldAddToHistory(this)) {
			this.undoHistory.push(command);
			this.commandHistoryDirty = true;
		}
		if(purgeRedoStack) {
			this.redoHistory = [];
		}
	}
	,undoCommand: function(command) {
		command.undo(this);
		this.redoHistory.push(command);
		this.commandHistoryDirty = true;
	}
	,undoLastCommand: function() {
		var command = this.undoHistory.pop();
		if(command == null) {
			haxe_Log.trace("No actions to undo.",{ fileName : "source/funkin/ui/debug/charting/ChartEditorState.hx", lineNumber : 5805, className : "funkin.ui.debug.charting.ChartEditorState", methodName : "undoLastCommand"});
			return;
		}
		this.undoCommand(command);
	}
	,redoLastCommand: function() {
		var command = this.redoHistory.pop();
		if(command == null) {
			haxe_Log.trace("No actions to redo.",{ fileName : "source/funkin/ui/debug/charting/ChartEditorState.hx", lineNumber : 5819, className : "funkin.ui.debug.charting.ChartEditorState", methodName : "redoLastCommand"});
			return;
		}
		this.performCommand(command,false);
	}
