	,updateGridHeight: function() {
		if(this.get_playheadPositionInMs() > this.get_songLengthInMs()) {
			this.set_playheadPositionInMs(this.get_songLengthInMs());
		}
		if(this.gridTiledSprite != null) {
			this.gridTiledSprite.set_height(this.get_songLengthInPixels());
		}
		if(this.measureTicks != null) {
			this.measureTicks.setHeight(this.get_songLengthInPixels());
		}
		var songCutoffPointSteps = this.get_songLengthInSteps() - 0.1;
		var songCutoffPointMs = funkin_Conductor.get_instance().getStepTimeInMs(songCutoffPointSteps);
		this.set_currentSongChartNoteData(funkin_data_song_SongDataUtils.clampSongNoteData(this.get_currentSongChartNoteData(),0.0,songCutoffPointMs));
		this.set_currentSongChartEventData(funkin_data_song_SongDataUtils.clampSongEventData(this.get_currentSongChartEventData(),0.0,songCutoffPointMs));
		this.set_scrollPositionInPixels(0);
		this.set_playheadPositionInPixels(0);
		this.set_notePreviewDirty(true);
		this.notePreviewViewportBoundsDirty = true;
		this.noteDisplayDirty = true;
		this.moveSongToScrollPosition();
	}
	,sortChartData: function() {
		this.get_currentSongChartNoteData().sort(function(a,b) {
			var Value1 = a.time;
			var Value2 = b.time;
			var result = 0;
			if(Value1 < Value2) {
				result = -1;
			} else if(Value1 > Value2) {
				result = 1;
			}
			return result;
		});
		this.get_currentSongChartEventData().sort(function(a,b) {
			var Value1 = a.time;
			var Value2 = b.time;
			var result = 0;
			if(Value1 < Value2) {
				result = -1;
			} else if(Value1 > Value2) {
				result = 1;
			}
			return result;
		});
	}
