funkin_ui_debug_charting_commands_PasteItemsCommand.__name__ = "funkin.ui.debug.charting.commands.PasteItemsCommand";
funkin_ui_debug_charting_commands_PasteItemsCommand.__interfaces__ = [funkin_ui_debug_charting_commands_ChartEditorCommand];
funkin_ui_debug_charting_commands_PasteItemsCommand.prototype = {
	targetTimestamp: null
	,addedNotes: null
	,addedEvents: null
	,execute: function(state) {
		var currentClipboard = funkin_data_song_SongDataUtils.readItemsFromClipboard();
		if(currentClipboard.valid != true) {
			funkin_ui_debug_charting_handlers_ChartEditorNotificationHandler.error(state,"Failed to Paste","Could not parse clipboard contents.");
			return;
		}
		var stepEndOfSong = funkin_Conductor.get_instance().getTimeInSteps(state.get_songLengthInMs());
		var stepCutoff = stepEndOfSong - 1.0;
		var msCutoff = funkin_Conductor.get_instance().getStepTimeInMs(stepCutoff);
		this.addedNotes = funkin_data_song_SongDataUtils.offsetSongNoteData(currentClipboard.notes,this.targetTimestamp | 0);
		this.addedNotes = funkin_data_song_SongDataUtils.clampSongNoteData(this.addedNotes,0.0,msCutoff);
		this.addedEvents = funkin_data_song_SongDataUtils.offsetSongEventData(currentClipboard.events,this.targetTimestamp | 0);
		this.addedEvents = funkin_data_song_SongDataUtils.clampSongEventData(this.addedEvents,0.0,msCutoff);
		state.set_currentSongChartNoteData(state.get_currentSongChartNoteData().concat(this.addedNotes));
		state.set_currentSongChartEventData(state.get_currentSongChartEventData().concat(this.addedEvents));
		state.set_currentNoteSelection(this.addedNotes.slice());
		state.currentEventSelection = this.addedEvents.slice();
		state.set_saveDataDirty(true);
		state.noteDisplayDirty = true;
		state.set_notePreviewDirty(true);
		state.sortChartData();
		funkin_ui_debug_charting_handlers_ChartEditorNotificationHandler.success(state,"Paste Successful","Successfully pasted clipboard contents.");
	}
	,undo: function(state) {
		funkin_ui_debug_charting_handlers_ChartEditorAudioHandler.playSound(state,funkin_Paths.sound("chartingSounds/undo"));
		state.set_currentSongChartNoteData(funkin_data_song_SongDataUtils.subtractNotes(state.get_currentSongChartNoteData(),this.addedNotes));
		state.set_currentSongChartEventData(funkin_data_song_SongDataUtils.subtractEvents(state.get_currentSongChartEventData(),this.addedEvents));
		state.set_currentNoteSelection([]);
		state.currentEventSelection = [];
		state.set_saveDataDirty(true);
		state.noteDisplayDirty = true;
		state.set_notePreviewDirty(true);
		state.sortChartData();
	}
	,shouldAddToHistory: function(state) {
		if(this.addedNotes.length <= 0) {
			return this.addedEvents.length > 0;
		} else {
			return true;
		}
	}
	,toString: function() {
		var currentClipboard = funkin_data_song_SongDataUtils.readItemsFromClipboard();
		var len = currentClipboard.notes.length + currentClipboard.events.length;
		if(currentClipboard.notes.length == 0) {
			return "Paste " + len + " Events";
		} else if(currentClipboard.events.length == 0) {
			return "Paste " + len + " Notes";
		} else {
			return "Paste " + len + " Items";
		}
	}
	,__class__: funkin_ui_debug_charting_commands_PasteItemsCommand
};
