	state.songMetadata = newSongMetadata;
	state.songChartData = newSongChartData;
	funkin_Conductor.get_instance().forceBPM(null);
	funkin_Conductor.get_instance().instrumentalOffset = state.get_currentInstrumentalOffset();
	funkin_Conductor.get_instance().mapTimeChanges(state.get_currentSongMetadata().timeChanges);
